def tokenize(text):
    return text.replace("(", " ( ").replace(")", " ) ").split()

def read(tokens):
    token = tokens.pop(0)
    if token == "(":
        items = []
        while tokens[0] != ")":
            items.append(read(tokens))
        tokens.pop(0)                      # the closing )
        return items
    try:
        return int(token)
    except ValueError:
        return token                       # a symbol, kept as a string


# Step 2: evaluate.  A number is itself.  A list is an operator and its operands.
def evaluate(x):
    if isinstance(x, int):
        return x
    op, *args = x
    values = [evaluate(a) for a in args]   # post-order: children first
    if op == "+":
        return sum(values)
    if op == "*":
        result = 1
        for v in values:
            result *= v
        return result
    if op == "-":
        return values[0] - values[1]
    raise NameError(f"unknown operator {op}")


def run(text):
    return evaluate(read(tokenize(text)))


print(run("(+ 1 (* 2 3))"))
print(run("(- 10 (+ 1 2))"))
